final class SpyMailer: Mailer {
    private(set) var sent: [(to: String, body: String)] = []
    private let real: Mailer
    init(wrapping real: Mailer) { self.real = real }

    func send(to: String, body: String) {
        sent.append((to, body))
        real.send(to: to, body: body)          // real behaviour runs
    }
}
